INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Online-USV nur für kritische Systeme geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für weniger kritische Systeme nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar, aber teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Online-USV?', 3, '[{"text": "Höchste Stromsicherheit", "correct": true, "because": "Dauerhafte Umwandlung schützt"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Stromschutz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Online-USV?', 5, '[{"text": "Dauerhafte Stromumwandlung", "correct": true, "because": "Kontinuierliche Versorgung"}, {"text": "Spannungsregulierung", "correct": true, "because": "Stabilisiert Strom"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Online-USV bietet höchste Sicherheit. b) Sie ist kostengünstig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Höhere Kosten für Qualität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Online-USV?', 4, '[{"text": "Batterielebensdauer", "correct": false, "because": "Wichtig für Zuverlässigkeit"}, {"text": "Stromqualität", "correct": false, "because": "Kern der Funktion"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Online-USV auch vor Spannungsschwankungen schützt?', 2, '[{"text": "Ja", "correct": true, "because": "Dauerhafte Umwandlung gleicht aus"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme profitieren von einer Online-USV?', 3, '[{"text": "Kritische Server", "correct": true, "because": "Brauchen höchste Sicherheit"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Online-USV?', 5, '[{"text": "Ununterbrochene Stromversorgung", "correct": true, "because": "Dauerhafte Umwandlung"}, {"text": "Schutz vor Stromschwankungen", "correct": true, "because": "Stabile Ausgabe"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Online-USV ist teurer als Offline-USV. b) Sie ist nur für kurze Ausfälle geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für längere Ausfälle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Online-USV?', 4, '[{"text": "Batterie-Backup", "correct": false, "because": "Überbrückt Ausfälle"}, {"text": "Spannungsregelung", "correct": false, "because": "Sichert Stromqualität"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Online-USV immer aktiv?', 2, '[{"text": "Ja", "correct": true, "because": "Dauerhafte Stromumwandlung"}, {"text": "Nein", "correct": false, "because": "Kein Standby-Modus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme schützt eine Online-USV besonders?', 4, '[{"text": "Rechenzentren", "correct": true, "because": "Hohe Sicherheitsanforderungen"}, {"text": "Medizinische Geräte", "correct": true, "because": "Kritische Anwendungen"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Online-USV keine Batterie braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Batterie für Ausfälle nötig"}, {"text": "Ja", "correct": false, "because": "Backup ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Online-USV?', 3, '[{"text": "Stromqualität", "correct": true, "because": "Sichert kritische Systeme"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Schriftgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Online-USV schützt vor Stromausfällen. b) Sie ist günstiger als Offline-USV.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Höhere Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine Online-USV sicher?', 5, '[{"text": "Doppelte Stromumwandlung", "correct": true, "because": "Stabile Versorgung"}, {"text": "Batterie-Backup", "correct": true, "because": "Überbrückt Ausfälle"}, {"text": "Maximale Speicherung", "correct": false, "because": "Nicht relevant"}, {"text": "Datenbankdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Online-USV unwichtig?', 3, '[{"text": "Überlastschutz", "correct": false, "because": "Schützt Geräte"}, {"text": "Spannungsstabilität", "correct": false, "because": "Kernfunktion"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt eine Online-USV auch vor Überspannung?', 3, '[{"text": "Ja", "correct": true, "because": "Stabile Stromversorgung"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Online-USV Wartung benötigt?', 2, '[{"text": "Ja", "correct": true, "because": "Batterien und System überprüfen"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Wartung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Online-USV?', 4, '[{"text": "Dauerhafte Stromumwandlung", "correct": true, "because": "Höchste Sicherheit"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
